const listPolicyStopRevisionInputs = `-- name: ListPolicyStopRevisionInputs :many
SELECT id, run_id, kind, body, consumed_at, created_at, question_id, disposition, consumed_claim_generation, consumed_worker_id, applied_at, gate_binding, gate_revision, included_at, inclusion_reported, settled_at, superseded_by_stop_input_id FROM run_user_inputs
WHERE run_id = $1 AND kind = 'revise_plan'
  AND applied_at IS NULL AND settled_at IS NULL
  AND disposition IS DISTINCT FROM 'superseded'
  AND disposition IS DISTINCT FROM 'superseded_by_stop'
ORDER BY id
`

func (q *Queries) ListPolicyStopRevisionInputs(ctx context.Context, runID uuid.UUID) ([]RunUserInput, error) {
	rows, err := q.db.Query(ctx, listPolicyStopRevisionInputs, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RunUserInput{}
	for rows.Next() {
		var i RunUserInput
		if err := rows.Scan(
			&i.ID,
			&i.RunID,
			&i.Kind,
			&i.Body,
			&i.ConsumedAt,
			&i.CreatedAt,
			&i.QuestionID,
			&i.Disposition,
			&i.ConsumedClaimGeneration,
			&i.ConsumedWorkerID,
			&i.AppliedAt,
			&i.GateBinding,
			&i.GateRevision,
			&i.IncludedAt,
			&i.InclusionReported,
			&i.SettledAt,
			&i.SupersededByStopInputID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setPolicyCandidateCrossCheckAssociation = `-- name: SetPolicyCandidateCrossCheckAssociation :execrows
UPDATE runs
SET policy_candidate_cross_check_id = $1::uuid
WHERE id = $2::uuid AND worker_id = $3::uuid
  AND claim_generation = $4::bigint
  AND claim_released_at IS NULL AND policy_stop_resolution IS NULL
`

type SetPolicyCandidateCrossCheckAssociationParams struct {
	CrossCheckID    uuid.UUID `json:"cross_check_id"`
	LeadRunID       uuid.UUID `json:"lead_run_id"`
	WorkerID        uuid.UUID `json:"worker_id"`
	ClaimGeneration int64     `json:"claim_generation"`
}

func (q *Queries) SetPolicyCandidateCrossCheckAssociation(ctx context.Context, arg SetPolicyCandidateCrossCheckAssociationParams) (int64, error) {
	result, err := q.db.Exec(ctx, setPolicyCandidateCrossCheckAssociation,
		arg.CrossCheckID,
		arg.LeadRunID,
		arg.WorkerID,
		arg.ClaimGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setPolicyRevisionSource = `-- name: SetPolicyRevisionSource :execrows
UPDATE runs SET policy_revision_source = $1::jsonb
WHERE id = $2::uuid AND worker_id = $3::uuid
 AND claim_generation = $4::bigint AND claim_generation > 0
 AND claim_released_at IS NULL AND status IN ('claimed','running','awaiting_approval')
 AND harness='codex' AND NOT interactive AND target_run_id IS NULL
 AND kind IN ('issue','task','prompt','self_improve') AND policy_stop_resolution IS NULL
`

type SetPolicyRevisionSourceParams struct {
	Source          []byte    `json:"source"`
	RunID           uuid.UUID `json:"run_id"`
	WorkerID        uuid.UUID `json:"worker_id"`
	ClaimGeneration int64     `json:"claim_generation"`
}

// Caller holds the worker/run claim transaction and authenticates finite coverage.
func (q *Queries) SetPolicyRevisionSource(ctx context.Context, arg SetPolicyRevisionSourceParams) (int64, error) {
	result, err := q.db.Exec(ctx, setPolicyRevisionSource,
		arg.Source,
		arg.RunID,
		arg.WorkerID,
		arg.ClaimGeneration,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settlePolicyStopCrossCheck = `-- name: SettlePolicyStopCrossCheck :execrows
UPDATE cross_checks
SET revision_disposition = 'superseded_by_stop', revision_settled_at = now(),
    revision_superseded_by_stop_input_id = $1::bigint
WHERE lead_run_id = $2 AND id = $3 AND stage = 'plan'
  AND verdict = 'revise' AND decided_at IS NOT NULL
  AND revision_disposition IS NULL AND revision_settled_at IS NULL
  AND revision_superseded_by_stop_input_id IS NULL
`

type SettlePolicyStopCrossCheckParams struct {
	ScopeInputID int64     `json:"scope_input_id"`
	RunID        uuid.UUID `json:"run_id"`
	CrossCheckID uuid.UUID `json:"cross_check_id"`
}

// Approve association witnesses are deliberately excluded.
func (q *Queries) SettlePolicyStopCrossCheck(ctx context.Context, arg SettlePolicyStopCrossCheckParams) (int64, error) {
	result, err := q.db.Exec(ctx, settlePolicyStopCrossCheck, arg.ScopeInputID, arg.RunID, arg.CrossCheckID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settlePolicyStopRevisionInput = `-- name: SettlePolicyStopRevisionInput :execrows
UPDATE run_user_inputs
SET disposition = 'superseded_by_stop', settled_at = now(),
    superseded_by_stop_input_id = $1::bigint
WHERE run_id = $2 AND id = $3::bigint AND kind = 'revise_plan'
  AND applied_at IS NULL AND included_at IS NULL AND settled_at IS NULL
  AND disposition IS NULL AND superseded_by_stop_input_id IS NULL
`

type SettlePolicyStopRevisionInputParams struct {
	ScopeInputID int64     `json:"scope_input_id"`
	RunID        uuid.UUID `json:"run_id"`
	InputID      int64     `json:"input_id"`
}

// Caller holds the parent run lock and visits manifest input IDs in ascending order.
func (q *Queries) SettlePolicyStopRevisionInput(ctx context.Context, arg SettlePolicyStopRevisionInputParams) (int64, error) {
	result, err := q.db.Exec(ctx, settlePolicyStopRevisionInput, arg.ScopeInputID, arg.RunID, arg.InputID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
